"""
Batch adaptive signal filtering with centered robust smoothing and
prominence-selected monotone trend projection.

Returned samples are right-endpoint aligned: output[i] corresponds to input
index i + window_size - 1.
"""
import numpy as np

try:
    from scipy.signal import medfilt, savgol_filter
    _HAVE_SCIPY = True
except Exception:
    _HAVE_SCIPY = False


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float).ravel()
    if x.size < window_size:
        raise ValueError(
            f"Input signal length ({x.size}) must be >= window_size ({window_size})"
        )
    return np.convolve(
        x, np.ones(int(window_size), dtype=float) / float(window_size), mode="valid"
    )


def _fill_nonfinite(x):
    x = np.asarray(x, dtype=float).ravel().copy()
    good = np.isfinite(x)
    if good.all():
        return x
    if not good.any():
        return np.zeros_like(x)
    idx = np.arange(x.size)
    x[~good] = np.interp(idx[~good], idx[good], x[good])
    return x


def _odd_width(target, n, minimum=5):
    """Largest safe odd width not exceeding n."""
    if n < minimum:
        return 0
    width = min(int(target), n if n % 2 else n - 1)
    if width < minimum:
        width = minimum if minimum <= n else 0
    return width if width % 2 else width - 1


def _pav_increasing(values):
    """Unit-weight least-squares isotonic regression."""
    values = np.asarray(values, dtype=float)
    n = values.size
    if n <= 1:
        return values.copy()

    means = []
    counts = []
    for value in values:
        means.append(float(value))
        counts.append(1)
        while len(means) >= 2 and means[-2] > means[-1]:
            total = counts[-2] + counts[-1]
            merged = (
                means[-2] * counts[-2] + means[-1] * counts[-1]
            ) / total
            means[-2:] = [merged]
            counts[-2:] = [total]

    out = np.empty(n, dtype=float)
    pos = 0
    for mean, count in zip(means, counts):
        out[pos:pos + count] = mean
        pos += count
    return out


def _monotone_projection(z, threshold):
    """
    Remove shallow extrema, then make each retained excursion monotone.
    The projection controls reversal topology rather than merely shrinking
    individual sample differences.
    """
    z = np.asarray(z, dtype=float)
    n = z.size
    if n < 4:
        return z.copy()

    d = np.diff(z)
    signs = np.sign(d)

    # Carry the last nonzero derivative sign through short exact plateaus.
    last = 0.0
    for i in range(signs.size):
        if signs[i] != 0.0:
            last = signs[i]
        elif last != 0.0:
            signs[i] = last
    last = 0.0
    for i in range(signs.size - 1, -1, -1):
        if signs[i] != 0.0:
            last = signs[i]
        elif last != 0.0:
            signs[i] = last

    extrema = [0]
    for i in range(1, signs.size):
        if signs[i] != 0.0 and signs[i - 1] != 0.0 and signs[i] != signs[i - 1]:
            extrema.append(i)
    extrema.append(n - 1)

    # Stack-style repeated pruning of extrema whose smaller neighboring
    # excursion is below the robust prominence requirement.
    prominence = max(float(threshold), 1e-12)
    changed = True
    while changed and len(extrema) > 2:
        changed = False
        keep = [extrema[0]]
        j = 1
        while j < len(extrema) - 1:
            left = keep[-1]
            mid = extrema[j]
            right = extrema[j + 1]
            a = abs(z[mid] - z[left])
            b = abs(z[right] - z[mid])
            if min(a, b) < prominence:
                changed = True
            else:
                keep.append(mid)
            j += 1
        keep.append(extrema[-1])
        extrema = keep

    out = np.empty_like(z)
    for k in range(len(extrema) - 1):
        left, right = extrema[k], extrema[k + 1]
        segment = z[left:right + 1]
        if z[right] >= z[left]:
            fitted = _pav_increasing(segment)
        else:
            fitted = -_pav_increasing(-segment)

        if k == 0:
            out[left:right + 1] = fitted
        else:
            # The neighboring segment already owns the shared boundary.
            out[left + 1:right + 1] = fitted[1:]

    return out


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = np.asarray(x, dtype=float).ravel()
    window_size = int(window_size)
    if x.size < window_size:
        raise ValueError(
            f"Input signal length ({x.size}) must be >= window_size ({window_size})"
        )

    x = _fill_nonfinite(x)
    n = x.size
    if n < 5 or window_size < 3:
        return x[window_size - 1:].copy()

    if _HAVE_SCIPY:
        pre = medfilt(x, kernel_size=5)

        long_width = _odd_width(2 * window_size + 1, n)
        short_width = _odd_width(window_size + 1, n)
        if long_width == 0 or short_width == 0:
            smooth = x.copy()
        else:
            long_smooth = savgol_filter(
                pre, long_width, min(3, long_width - 1), mode="interp"
            )
            short_smooth = savgol_filter(
                pre, short_width, min(2, short_width - 1), mode="interp"
            )

            short_residual = x - short_smooth
            short_mad = 1.4826 * np.median(
                np.abs(short_residual - np.median(short_residual))
            )
            short_mad = max(float(short_mad), 1e-12)

            disagreement = np.abs(short_smooth - long_smooth)
            gate = np.clip(
                (disagreement - short_mad) / (2.0 * short_mad), 0.0, 1.0
            )

            # Responsive component is allowed when scales demonstrably differ.
            smooth = long_smooth + 0.35 * gate * (short_smooth - long_smooth)
    else:
        radius = max(2, min(window_size, max(2, (n - 1) // 2)))
        kernel = np.ones(2 * radius + 1, dtype=float)
        kernel /= kernel.size
        smooth = np.convolve(np.pad(x, radius, mode="reflect"), kernel, mode="valid")

    residual = x - smooth
    mad_scale = 1.4826 * np.median(np.abs(residual - np.median(residual)))
    base_threshold = max(0.03 * float(np.std(x)), 0.50 * float(mad_scale), 1e-12)

    # Prominence slightly above the old play threshold removes shallow
    # turning topology, while isotonic segments retain larger movements.
    stabilized = _monotone_projection(smooth, 1.25 * base_threshold)

    return np.asarray(stabilized[window_size - 1:], dtype=float)


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    np.random.seed(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(np.random.randn(length) * 0.05)
    noisy_signal = clean_signal + np.random.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(
    noisy_signal=None, signal_length=1000, noise_level=0.3, window_size=20
):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(signal_length, noise_level)
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is None:
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered_signal),
        }

    delay = int(window_size) - 1
    aligned_clean = clean_signal[delay:delay + len(filtered_signal)]
    aligned_noisy = noisy_signal[delay:delay + len(filtered_signal)]

    m = min(len(filtered_signal), len(aligned_clean))
    filtered_signal = filtered_signal[:m]
    aligned_clean = aligned_clean[:m]
    aligned_noisy = aligned_noisy[:m]

    correlation = np.corrcoef(filtered_signal, aligned_clean)[0, 1] if m > 1 else 0
    before = np.var(aligned_noisy - aligned_clean)
    after = np.var(filtered_signal - aligned_clean)
    reduction = (before - after) / before if before > 0 else 0

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": aligned_clean,
        "noisy_signal": aligned_noisy,
        "correlation": correlation,
        "noise_reduction": reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")
